window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[5]={"id":"005","numero":5,"titre":"Gestion des erreurs et plaintes, aléa thérapeutique","objectifs":[{"id":"5-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la responsabilité sanction/indemnisation","contenu":"<p>La <strong><span class=\"kw-def\">responsabilité médicale</span></strong> répond à <strong>deux finalités distinctes</strong> selon ce que la société attend de la mise en cause du médecin : <strong><span class=\"kw-def\">punir</span></strong> un comportement réprouvé, ou <strong><span class=\"kw-def\">réparer</span></strong> le préjudice subi par la victime.</p>\n\n<h4 class=\"kw-def\">Responsabilité-sanction (fonction répressive)</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">But</span></strong> = <span class=\"kw-def\">sanctionner</span> l'auteur d'un comportement réprouvé par la société ; elle <span class=\"kw-ci\">ne répare pas le dommage</span>.</li>\n  <li><strong><span class=\"kw-def\">Responsabilité pénale</span></strong> : <span class=\"kw-clinique\">amende</span>, <span class=\"kw-clinique\">emprisonnement</span>, <span class=\"kw-clinique\">interdiction d'exercice</span>.</li>\n  <li><strong><span class=\"kw-def\">Responsabilité disciplinaire</span></strong> (ordinale) : <span class=\"kw-clinique\">avertissement</span>, <span class=\"kw-clinique\">blâme</span>, <span class=\"kw-clinique\">interdiction d'exercer</span>, <span class=\"kw-clinique\">radiation</span>.</li>\n</ul>\n\n<h4 class=\"kw-def\">Responsabilité-indemnisation (fonction réparatrice)</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">But</span></strong> = <span class=\"kw-def\">indemniser le préjudice</span> de la victime par des <span class=\"kw-clinique\">dommages et intérêts</span> (pris en charge par l'assurance).</li>\n  <li><strong><span class=\"kw-def\">Responsabilité civile</span></strong> : <span class=\"kw-etio\">médecin libéral</span>, <span class=\"kw-etio\">établissement de santé privé</span> &rarr; <span class=\"kw-clinique\">tribunal judiciaire</span>.</li>\n  <li><strong><span class=\"kw-def\">Responsabilité administrative</span></strong> : <span class=\"kw-etio\">médecin salarié du service public hospitalier</span> &rarr; <span class=\"kw-clinique\">tribunal administratif</span>.</li>\n</ul>\n\n<table >\n  <thead><tr><th>Responsabilité</th><th>Finalité</th><th>Qui ?</th><th>Juridiction</th><th>Conséquence</th></tr></thead>\n  <tbody>\n    <tr><td><strong>Civile</strong></td><td><span class=\"kw-def\">Indemnisation</span></td><td>Médecins libéraux, ES privés</td><td>Tribunal judiciaire</td><td>Dommages et intérêts</td></tr>\n    <tr><td><strong>Administrative</strong></td><td><span class=\"kw-def\">Indemnisation</span></td><td>Médecins salariés (public)</td><td>Tribunal administratif</td><td>Dommages et intérêts</td></tr>\n    <tr><td><strong>Pénale</strong></td><td><span class=\"kw-def\">Sanction</span></td><td>Tous les médecins</td><td>Tribunal correctionnel</td><td>Amende, prison</td></tr>\n    <tr><td><strong>Disciplinaire</strong></td><td><span class=\"kw-def\">Sanction</span></td><td>Tous les médecins</td><td>Chambre disciplinaire de l'Ordre</td><td>Avertissement &rarr; radiation</td></tr>\n  </tbody>\n</table>\n\n<div class=\"callout callout-info\">Les différentes responsabilités sont <strong>indépendantes</strong> et peuvent se <span class=\"kw-alerte\">cumuler</span> pour un même fait. Au pénal, la victime peut se constituer <strong><span class=\"kw-def\">partie civile</span></strong> pour obtenir, en parallèle de la sanction, l'<span class=\"kw-def\">indemnisation</span> de son dommage.</div>","frequence":5},{"id":"5-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la responsabilité pénale","contenu":"<p>La <strong><span class=\"kw-def\">responsabilité pénale</span></strong> a une <strong><span class=\"kw-def\">fonction répressive</span></strong> : elle <span class=\"kw-def\">sanctionne</span> un comportement réprouvé par la société. Elle ne peut être engagée <strong><span class=\"kw-alerte\">que si l'infraction est prévue par le Code pénal</span></strong> et ne permet <span class=\"kw-ci\">pas la réparation du dommage</span> (rôle dévolu aux responsabilités civile ou administrative).</p>\n\n<h4 class=\"kw-def\">Caractéristiques</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Toujours personnelle</span></strong> : concerne tous les médecins quel que soit leur statut, <strong><span class=\"kw-alerte\">internes compris</span></strong>.</li>\n  <li>Peut aussi viser les <strong><span class=\"kw-etio\">établissements de santé</span></strong> (personnes morales).</li>\n  <li>Poursuites engagées par le <strong><span class=\"kw-def\">procureur de la République</span></strong> : classement sans suite, renvoi, ou <span class=\"kw-clinique\">information judiciaire</span> (la règle en matière médicale).</li>\n  <li>La victime peut se constituer <strong><span class=\"kw-def\">partie civile</span></strong> pour obtenir une indemnisation lors du même procès.</li>\n</ul>\n\n<h4 class=\"kw-def\">Les 3 catégories d'infractions</h4>\n<table >\n  <thead><tr><th>Infraction</th><th>Juridiction</th><th>Peine</th></tr></thead>\n  <tbody>\n    <tr><td><strong><span class=\"kw-def\">Contravention</span></strong></td><td>Tribunal de police</td><td><span class=\"kw-clinique\">Amende</span></td></tr>\n    <tr><td><strong><span class=\"kw-def\">Délit</span></strong></td><td>Tribunal correctionnel</td><td><span class=\"kw-clinique\">Emprisonnement</span> + amende</td></tr>\n    <tr><td><strong><span class=\"kw-def\">Crime</span></strong></td><td>Cour d'assises</td><td><span class=\"kw-clinique\">Réclusion criminelle</span></td></tr>\n  </tbody>\n</table>\n<div class=\"callout callout-info\">Les infractions reprochées au médecin relèvent <strong>habituellement du tribunal correctionnel</strong> (délits).</div>\n\n<h4 class=\"kw-def\">Infractions propres à l'exercice médical</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Violation d'un devoir d'humanisme</span></strong> : <span class=\"kw-clinique\">faux certificats</span>, <span class=\"kw-clinique\">violation du secret professionnel</span>, <strong><span class=\"kw-alerte\">non-assistance à personne en péril</span></strong>.</li>\n  <li><strong><span class=\"kw-def\">Homicide / blessures involontaires</span></strong> : la majorité des cas ; exige un <span class=\"kw-def\">lien de causalité</span> entre faute et dommage (direct, ou indirect si faute <span class=\"kw-def\">qualifiée</span>).</li>\n  <li><strong><span class=\"kw-def\">Homicide / blessures volontaires</span></strong> (rares) : <span class=\"kw-etio\">euthanasie</span>, <span class=\"kw-etio\">défaut de consentement</span>, actes hors conditions légales (IVG hors délais...).</li>\n</ul>\n<div class=\"callout callout-warn\">&#9888; Le <strong><span class=\"kw-def\">défaut d'information</span></strong> du patient <span class=\"kw-ci\">n'est PAS une infraction pénale</span> ; il relève de la responsabilité <span class=\"kw-def\">civile</span>.</div>","frequence":3},{"id":"5-3","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la responsabilité civile","contenu":"<p>La <strong><span class=\"kw-def\">responsabilité civile</span></strong> (RC) est une responsabilité <strong><span class=\"kw-def\">indemnitaire</span></strong> : elle vise à <span class=\"kw-def\">réparer le préjudice</span> de la victime par des <span class=\"kw-clinique\">dommages et intérêts</span> (pris en charge par l'assurance). Référence : <strong><span class=\"kw-def\">Code civil</span></strong>.</p>\n\n<h4 class=\"kw-def\">Trois conditions cumulatives</h4>\n<ul>\n  <li>Une <strong><span class=\"kw-def\">faute</span></strong> (que le patient doit prouver) ;</li>\n  <li>Un <strong><span class=\"kw-def\">préjudice</span></strong> (dommage) ;</li>\n  <li>Un <strong><span class=\"kw-def\">lien de causalité</span></strong> certain entre les deux.</li>\n</ul>\n\n<h4 class=\"kw-def\">Qui relève de la RC ?</h4>\n<ul>\n  <li><strong><span class=\"kw-clinique\">OUI</span></strong> &mdash; <strong><span class=\"kw-etio\">médecins libéraux</span></strong> et <strong><span class=\"kw-etio\">établissements de santé privés</span></strong> ;</li>\n  <li><strong><span class=\"kw-clinique\">OUI</span></strong> &mdash; praticiens hospitaliers dans le cadre de leur <span class=\"kw-etio\">secteur d'activité libérale</span> ;</li>\n  <li><span class=\"kw-ci\">NON</span> &mdash; <strong><span class=\"kw-etio\">médecins salariés</span></strong> d'un établissement privé (sauf s'ils outrepassent leur mission) : c'est l'employeur qui répond.</li>\n</ul>\n\n<h4 class=\"kw-def\">Juridiction</h4>\n<p><strong><span class=\"kw-def\">Tribunal judiciaire</span></strong> (ex-tribunal de grande instance) &rarr; <span class=\"kw-def\">cour d'appel</span> &rarr; <span class=\"kw-def\">cour de cassation</span> (chambres civiles).</p>\n\n<div class=\"callout callout-info\">La <strong><span class=\"kw-def\">faute personnelle détachable du service</span></strong> d'un médecin hospitalier (intention de nuire, gravité exceptionnelle) engage sa <strong><span class=\"kw-def\">responsabilité civile personnelle</span></strong>, et non l'administration.</div>","frequence":0},{"id":"5-4","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la responsabilité administrative","contenu":"<p>La <strong><span class=\"kw-def\">responsabilité administrative</span></strong> est la responsabilité <strong><span class=\"kw-def\">indemnitaire</span></strong> qui s'applique aux <strong><span class=\"kw-etio\">médecins salariés du service public hospitalier</span></strong> (agents publics). Elle aboutit à des <span class=\"kw-clinique\">dommages et intérêts</span> versés à la victime. Référence : <strong><span class=\"kw-def\">Code de justice administrative</span></strong>.</p>\n\n<h4 class=\"kw-def\">Juridiction</h4>\n<p><strong><span class=\"kw-def\">Tribunal administratif</span></strong> &rarr; <span class=\"kw-def\">cour administrative d'appel</span> &rarr; <span class=\"kw-def\">Conseil d'État</span>.</p>\n\n<h4 class=\"kw-def\">Fautes engageant le service public</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Faute de service</span></strong> : faute de l'agent public dans l'exercice de ses fonctions (pendant le service, avec les moyens du service, sans intérêt personnel) ;</li>\n  <li><strong><span class=\"kw-def\">Faute dans l'organisation et le fonctionnement du service</span></strong> : <span class=\"kw-clinique\">surveillance insuffisante</span> des patients, <span class=\"kw-clinique\">mauvais entretien</span> des locaux/matériel, <span class=\"kw-clinique\">défaut de coordination</span> entre médecins.</li>\n</ul>\n\n<div class=\"callout callout-warn\">&#9888; La <strong><span class=\"kw-def\">faute personnelle détachable du service</span></strong> engage la <span class=\"kw-def\">responsabilité civile personnelle</span> du médecin (et non l'hôpital) : faute sans lien avec le service, ou commise dans le service mais détachable par l'<span class=\"kw-alerte\">intention de nuire</span> ou son <span class=\"kw-alerte\">exceptionnelle gravité</span> (ex. refus du chirurgien de garde de se déplacer pour un blessé grave annoncé par l'interne).</div>","frequence":2},{"id":"5-5","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la responsabilité disciplinaire","contenu":"<p>La <strong><span class=\"kw-def\">responsabilité disciplinaire</span></strong> (ordinale) est encourue devant les <strong><span class=\"kw-etio\">instances de l'Ordre des médecins</span></strong>. Elle est <strong><span class=\"kw-alerte\">indépendante</span></strong> des actions civiles ou pénales (cumul possible) et sanctionne tout <strong><span class=\"kw-def\">manquement aux règles de déontologie</span></strong> (Code de déontologie médicale).</p>\n\n<h4 class=\"kw-def\">Faute disciplinaire</h4>\n<ul>\n  <li>Violation d'une <span class=\"kw-def\">règle déontologique</span>, qu'elle soit écrite ou non ;</li>\n  <li>En général liée à l'<span class=\"kw-etio\">activité professionnelle</span>, mais <strong>pas exclusivement</strong> : un acte de la <span class=\"kw-etio\">vie privée</span> portant atteinte à l'honneur de la profession peut suffire (ex. médecin ivre sur la voie publique).</li>\n</ul>\n\n<h4 class=\"kw-def\">Juridictions ordinales</h4>\n<ul>\n  <li>1<sup>re</sup> instance : <strong><span class=\"kw-def\">chambre disciplinaire du conseil régional</span></strong> de l'Ordre ;</li>\n  <li>Appel : <strong><span class=\"kw-def\">chambre disciplinaire du conseil national</span></strong> ;</li>\n  <li>Cassation : <strong><span class=\"kw-def\">Conseil d'État</span></strong>.</li>\n</ul>\n\n<h4 class=\"kw-def\">Sanctions (jamais pécuniaires)</h4>\n<ul>\n  <li><span class=\"kw-clinique\">Avertissement</span> ;</li>\n  <li><span class=\"kw-clinique\">Blâme</span> ;</li>\n  <li><strong><span class=\"kw-clinique\">Interdiction temporaire d'exercer</span></strong> (<span class=\"kw-chiffre\">&le; 3 ans</span>), éventuellement assortie d'un <span class=\"kw-clinique\">sursis</span> ;</li>\n  <li><strong><span class=\"kw-clinique\">Radiation</span></strong> du tableau de l'Ordre (relèvement possible après <span class=\"kw-chiffre\">3 ans</span>).</li>\n</ul>\n<div class=\"callout callout-warn\">&#9888; <strong>Aucune sanction pécuniaire</strong> (pas d'amende). La plainte d'un patient est d'abord transmise au <strong><span class=\"kw-def\">conseil départemental</span></strong>, qui a l'<strong>obligation de tenter une conciliation</strong> ; en cas d'échec, elle est transmise à la <span class=\"kw-def\">chambre disciplinaire régionale</span>.</div>","frequence":4},{"id":"5-6","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la responsabilité sans faute","contenu":"<p>Par principe (Code de la santé publique), les professionnels et établissements ne sont responsables qu'<strong>en cas de <span class=\"kw-def\">faute prouvée</span></strong>. Par exception, la loi a institué des régimes de <strong><span class=\"kw-def\">responsabilité sans faute</span></strong> : l'indemnisation est due alors qu'<strong><span class=\"kw-alerte\">aucune faute n'est exigée</span></strong>, à partir d'un autre <strong><span class=\"kw-def\">fait générateur</span></strong>.</p>\n\n<h4 class=\"kw-def\">Les 3 situations de responsabilité sans faute</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Infection nosocomiale</span></strong> contractée en établissement de santé (présomption de faute pesant sur l'établissement) ;</li>\n  <li><strong><span class=\"kw-def\">Accident médical non fautif</span></strong> (= <span class=\"kw-def\">aléa thérapeutique</span>) : complication <span class=\"kw-clinique\">imprévisible</span> et <span class=\"kw-clinique\">inévitable</span> ;</li>\n  <li><strong><span class=\"kw-def\">Défaut d'un produit de santé</span></strong> : produit n'offrant pas la sécurité légitimement attendue.</li>\n</ul>\n\n<h4 class=\"kw-def\">Indemnisation</h4>\n<ul>\n  <li>Au titre de la <strong><span class=\"kw-def\">solidarité nationale</span></strong>, par l'<strong><span class=\"kw-def\">ONIAM</span></strong>, lorsque le dommage présente des <strong><span class=\"kw-alerte\">conséquences anormales</span></strong> et atteint le <span class=\"kw-def\">seuil de gravité</span> ;</li>\n  <li>Anormalité = dommage plus grave que l'évolution naturelle attendue, <strong>ou</strong> de survenue <span class=\"kw-chiffre\">peu probable (&lt; 5 %)</span>.</li>\n</ul>\n<div class=\"callout callout-warn\">&#9888; En l'absence de faute, après indemnisation, l'<strong><span class=\"kw-def\">ONIAM ne peut pas se retourner</span></strong> contre l'assureur du professionnel ou de l'établissement (puisqu'il n'y a <span class=\"kw-ci\">pas de faute</span>).</div>","frequence":1},{"id":"5-7","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la faute","contenu":"<p>La <strong><span class=\"kw-def\">faute</span></strong> est le <strong><span class=\"kw-def\">fait générateur</span></strong> habituel de la responsabilité : il incombe au <strong>patient de la prouver</strong>. C'est un manquement à une obligation, apprécié par rapport à ce qu'aurait fait un praticien normalement diligent.</p>\n\n<h4 class=\"kw-def\">Faute technique</h4>\n<p>Violation des <strong><span class=\"kw-def\">données acquises de la science</span></strong> : <span class=\"kw-clinique\">non-respect des recommandations de bonnes pratiques</span> et de la <span class=\"kw-clinique\">littérature scientifique</span> médicale.</p>\n\n<h4 class=\"kw-def\">Violation d'un devoir d'humanisme</h4>\n<ul>\n  <li><strong><span class=\"kw-clinique\">Atteinte au secret professionnel</span></strong> ;</li>\n  <li><strong><span class=\"kw-clinique\">Défaut d'information</span></strong> ne permettant pas un <span class=\"kw-def\">consentement libre et éclairé</span>.</li>\n</ul>\n\n<h4 class=\"kw-def\">Gradation de la faute (au pénal)</h4>\n<table >\n  <thead><tr><th>Type</th><th>Définition</th></tr></thead>\n  <tbody>\n    <tr><td><strong><span class=\"kw-def\">Faute simple</span></strong></td><td><span class=\"kw-clinique\">Maladresse</span>, <span class=\"kw-clinique\">imprudence</span>, <span class=\"kw-clinique\">inattention</span></td></tr>\n    <tr><td><strong><span class=\"kw-def\">Faute qualifiée</span></strong></td><td>A créé ou contribué à créer la situation du dommage ; regroupe la faute délibérée et la faute caractérisée</td></tr>\n    <tr><td><strong><span class=\"kw-def\">Faute délibérée</span></strong></td><td>Violation <span class=\"kw-clinique\">consciente</span> d'une règle de prudence ou de sécurité prévue par la loi</td></tr>\n    <tr><td><strong><span class=\"kw-def\">Faute caractérisée</span></strong></td><td>Exposition à un <span class=\"kw-alerte\">risque de particulière gravité</span> que le médecin ne pouvait ignorer</td></tr>\n  </tbody>\n</table>\n<div class=\"callout callout-info\">Selon l'ordre de juridiction, la faute prend d'autres noms : <strong><span class=\"kw-def\">faute de service</span></strong> (responsabilité administrative) ou <strong><span class=\"kw-def\">faute disciplinaire</span></strong> = manquement à la déontologie (instances ordinales).</div>","frequence":0},{"id":"5-8","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’erreur médicale","contenu":"<p>L'<strong><span class=\"kw-def\">erreur médicale</span></strong> est un acte de soins (de <span class=\"kw-clinique\">prévention</span>, de <span class=\"kw-clinique\">diagnostic</span> ou de <span class=\"kw-clinique\">traitement</span>) qui s'écarte de ce qui aurait dû être fait. Elle est par nature <strong><span class=\"kw-def\">involontaire</span></strong> et <strong><span class=\"kw-def\">évitable</span></strong>, et peut <strong>ou non</strong> avoir entraîné un dommage pour le patient.</p>\n\n<h4 class=\"kw-def\">Typologie des erreurs</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Erreur par omission</span></strong> : une action nécessaire <span class=\"kw-clinique\">n'a pas été faite</span> ;</li>\n  <li><strong><span class=\"kw-def\">Erreur par commission</span></strong> : une action a été faite mais <span class=\"kw-clinique\">n'était pas utile</span> ;</li>\n  <li><strong><span class=\"kw-def\">Erreur d'exécution</span></strong> : une action a été <span class=\"kw-clinique\">mal réalisée</span> ;</li>\n  <li><strong><span class=\"kw-def\">Violation</span></strong> (non-conformité) : <span class=\"kw-clinique\">non-respect d'une recommandation</span> ou d'une règle professionnelle &mdash; <span class=\"kw-etio\">routinier</span> (mauvaise habitude), par <span class=\"kw-etio\">priorisation personnelle</span> (gagner du temps) ou <span class=\"kw-etio\">induit par le contexte</span> (suractivité, urgence).</li>\n</ul>\n\n<h4 class=\"kw-def\">Notions voisines (gestion des plaintes)</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Réclamation</span></strong> : démarche d'un patient/famille <span class=\"kw-clinique\">dénonçant un dysfonctionnement</span> ou une erreur dans les soins, adressée au chef de service, au directeur ou aux autorités sanitaires ;</li>\n  <li><strong><span class=\"kw-def\">Plainte</span></strong> : action de porter à la connaissance d'une <span class=\"kw-clinique\">autorité compétente</span> le tort subi par une personne qui s'estime <strong><span class=\"kw-alerte\">victime d'un préjudice</span></strong> à la suite d'une erreur.</li>\n</ul>\n\n<div class=\"callout callout-warn\">&#9888; Ne pas confondre l'<strong><span class=\"kw-def\">erreur</span></strong> (<span class=\"kw-clinique\">évitable</span>) avec l'<strong><span class=\"kw-def\">aléa thérapeutique</span></strong> (<span class=\"kw-alerte\">inévitable</span>, sans erreur ni faute).</div>","frequence":0},{"id":"5-9","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’accident médical et de l’affection iatrogène","contenu":"<p>L'<strong><span class=\"kw-def\">accident médical</span></strong> et l'<strong><span class=\"kw-def\">affection iatrogène</span></strong> désignent des <strong><span class=\"kw-def\">dommages liés aux soins</span></strong> survenant indépendamment de toute erreur ; ils font partie, avec l'<span class=\"kw-def\">infection nosocomiale</span>, du périmètre indemnisé par l'<span class=\"kw-def\">ONIAM</span>.</p>\n\n<h4 class=\"kw-def\">Accident médical</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Événement imprévu</span></strong> causant un <span class=\"kw-clinique\">dommage</span> au patient ;</li>\n  <li>Présentant un <strong><span class=\"kw-def\">lien de causalité certain</span></strong> avec l'<span class=\"kw-clinique\">acte médical</span> (<span class=\"kw-clinique\">diagnostic</span>, <span class=\"kw-clinique\">soin</span> ou <span class=\"kw-clinique\">prévention</span>).</li>\n</ul>\n\n<h4 class=\"kw-def\">Affection iatrogène</h4>\n<ul>\n  <li>Dommage dont la cause est <strong>l'acte de soin lui-même</strong> : les <span class=\"kw-clinique\">soins délivrés</span> ont <span class=\"kw-clinique\">causé le dommage</span> ;</li>\n  <li>&laquo; <span class=\"kw-def\">iatrogène</span> &raquo; = <span class=\"kw-etio\">provoqué par le médecin ou le traitement</span> (ex. <span class=\"kw-etio\">effet indésirable médicamenteux</span>).</li>\n</ul>\n\n<div class=\"callout callout-info\">Accident médical et affection iatrogène peuvent être <strong>fautifs</strong> (responsabilité du soignant engagée) ou <strong>non fautifs</strong> : dans ce dernier cas ils relèvent de l'<strong><span class=\"kw-def\">aléa thérapeutique</span></strong> et de la <span class=\"kw-def\">solidarité nationale</span> (<span class=\"kw-def\">ONIAM</span>) si le <span class=\"kw-def\">seuil de gravité</span> est atteint (<span class=\"kw-chiffre\">AIPP &gt; 24 %</span>).</div>","frequence":0},{"id":"5-10","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’infection nosocomiale","contenu":"<p>L'<strong><span class=\"kw-def\">infection nosocomiale</span></strong> est une <strong><span class=\"kw-def\">infection associée aux soins (IAS)</span></strong> <strong>acquise dans un établissement de santé</strong> : <strong><span class=\"kw-alerte\">absente à l'admission</span></strong> et survenant au décours de la prise en charge. L'<span class=\"kw-def\">IAS</span> est le concept large (tout le parcours de soins, ville comprise) ; l'infection nosocomiale en est le <strong>sous-ensemble hospitalier</strong>.</p>\n\n<h4 class=\"kw-def\">Délais repères</h4>\n<ul>\n  <li><strong><span class=\"kw-chiffre\">&gt; 48 h</span></strong> après l'admission lorsque le statut infectieux d'entrée est inconnu ;</li>\n  <li><strong><span class=\"kw-chiffre\">30 jours</span></strong> après une intervention (infection du site opératoire, <span class=\"kw-bio\">ISO</span>) ;</li>\n  <li><strong><span class=\"kw-chiffre\">1 an</span></strong> en cas de pose de <span class=\"kw-clinique\">matériel prothétique</span> ou d'implant.</li>\n</ul>\n\n<h4 class=\"kw-def\">Régime d'indemnisation particulier</h4>\n<ul>\n  <li><strong><span class=\"kw-etio\">Professionnel libéral</span></strong> : responsabilité <strong><span class=\"kw-def\">pour faute prouvée</span></strong> (le patient prouve faute + dommage + lien) ;</li>\n  <li><strong><span class=\"kw-etio\">Établissement de santé</span></strong> : <strong><span class=\"kw-def\">présomption de faute</span></strong> ; il doit prouver une <span class=\"kw-def\">cause étrangère</span> pour s'exonérer ;</li>\n  <li><strong><span class=\"kw-def\">ONIAM</span></strong> (solidarité nationale) si <span class=\"kw-chiffre\">AIPP &gt; 25 %</span> ou <strong><span class=\"kw-alerte\">décès</span></strong>.</li>\n</ul>\n<div class=\"callout callout-warn\">&#9888; Pour les infections survenues après le <span class=\"kw-chiffre\">1<sup>er</sup> janvier 2003</span>, l'<strong><span class=\"kw-def\">ONIAM</span></strong> peut exercer un <strong><span class=\"kw-def\">recours subrogatoire</span></strong> contre l'établissement s'il établit un <span class=\"kw-alerte\">manquement caractérisé</span> aux obligations réglementaires.</div>","frequence":2},{"id":"5-11","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’aléa thérapeutique","contenu":"<p>L'<strong><span class=\"kw-def\">aléa thérapeutique</span></strong> est un <strong><span class=\"kw-def\">événement indésirable</span></strong> dont la cause est une <strong>action de soins conforme</strong>, <strong><span class=\"kw-alerte\">sans erreur ni faute</span></strong>. Il correspond à la <strong><span class=\"kw-def\">réalisation d'un risque inhérent</span></strong> à l'acte de soin. Sa caractéristique majeure est son <strong><span class=\"kw-alerte\">inévitabilité</span></strong> (&ne; erreur, évitable).</p>\n\n<h4 class=\"kw-def\">Formes</h4>\n<p>L'aléa recouvre un <strong><span class=\"kw-def\">accident médical</span></strong>, une <strong><span class=\"kw-def\">affection iatrogène</span></strong> ou une <strong><span class=\"kw-def\">infection nosocomiale</span></strong> survenus <strong>sans responsabilité</strong> du professionnel ou de l'établissement.</p>\n\n<h4 class=\"kw-def\">Indemnisation par la solidarité nationale</h4>\n<ul>\n  <li>Prise en charge par l'<strong><span class=\"kw-def\">ONIAM</span></strong> au titre de la <strong><span class=\"kw-def\">solidarité nationale</span></strong> (et non par un assureur, faute de faute) ;</li>\n  <li>Conditionnée à des <strong><span class=\"kw-alerte\">conséquences anormales</span></strong> : dommage plus grave que l'évolution naturelle de la maladie, <strong>ou</strong> de survenue <span class=\"kw-chiffre\">peu probable (&lt; 5 %)</span> ;</li>\n  <li>Et à un <strong><span class=\"kw-def\">seuil de gravité</span></strong> : <span class=\"kw-chiffre\">AIPP &gt; 24 %</span>, ou ATAP / DFT <span class=\"kw-chiffre\">&ge; 50 %</span> pendant <span class=\"kw-chiffre\">&ge; 6 mois</span>.</li>\n</ul>\n<div class=\"callout callout-warn\">&#9888; Sont <strong>exclus</strong> du régime amiable : la <span class=\"kw-ci\">chirurgie esthétique</span> et l'<span class=\"kw-ci\">accouchement par voie basse</span>. Après indemnisation d'un aléa, l'<strong>ONIAM ne peut pas se retourner</strong> contre l'assureur (pas de faute).</div>","frequence":2},{"id":"5-12","rang":"B","rubrique":"Epidémiologie","titre":"Identifier les principaux facteurs conduisant à l’ouverture d’un contentieux à la suite d’un accident médical","contenu":"<p>L'ouverture d'un <strong><span class=\"kw-def\">contentieux</span></strong> après un accident médical dépend moins de la gravité technique que de la <strong><span class=\"kw-def\">qualité de la relation</span></strong> et de l'<strong><span class=\"kw-def\">information</span></strong> reçues par le patient. La prévention des contentieux repose essentiellement sur la qualité de l'information donnée.</p>\n\n<h4 class=\"kw-def\">Facteurs favorisant un contentieux</h4>\n<ul>\n  <li><strong><span class=\"kw-etio\">Information préalable insuffisante</span></strong> : le risque réalisé n'avait pas été expliqué de façon <span class=\"kw-clinique\">loyale, claire et appropriée</span> &rarr; complication moins bien acceptée ;</li>\n  <li><strong><span class=\"kw-etio\">Déni du dommage</span></strong> ou absence d'annonce après l'<span class=\"kw-def\">EIAS</span> : accroît la <span class=\"kw-clinique\">détresse</span> et la <span class=\"kw-clinique\">colère</span> du patient ;</li>\n  <li><strong><span class=\"kw-etio\">Détérioration de la relation médecin-malade</span></strong> et défaut de communication ;</li>\n  <li><strong><span class=\"kw-etio\">Sous-estimation du préjudice</span></strong> par le soignant (le dommage doit être apprécié du point de vue du patient).</li>\n</ul>\n\n<h4 class=\"kw-def\">Levier de prévention : l'annonce d'un dommage</h4>\n<ul>\n  <li><strong>Obligatoire</strong> et éthique : toute victime (ou ayant droit) doit être informée des <span class=\"kw-clinique\">circonstances</span> et <span class=\"kw-clinique\">causes</span> du dommage ;</li>\n  <li>Délivrée lors d'un <strong><span class=\"kw-def\">entretien</span></strong> ; le patient peut se faire <span class=\"kw-clinique\">assister</span> par un médecin ou une personne de son choix ;</li>\n  <li>Une annonce bien menée n'empêche pas l'<span class=\"kw-def\">indemnisation</span> (qui reste un <strong>droit</strong>) mais réduit le recours juridictionnel.</li>\n</ul>\n<div class=\"callout callout-warn\">&#9888; <strong>Ne pas informer</strong> le patient d'un événement indésirable <span class=\"kw-alerte\">expose à l'ouverture de procédures contentieuses</span>.</div>","frequence":0},{"id":"5-13","rang":"A","rubrique":"Définition","titre":"Facteurs humains : connaître la notion d’erreur humaine (typologie et facteurs favorisants)","contenu":"<p>L'<strong><span class=\"kw-def\">erreur humaine</span></strong> est rarement isolée : selon le <strong><span class=\"kw-def\">modèle de Reason</span></strong> (modèle du &laquo; fromage suisse &raquo;), elle n'est le plus souvent que la <strong>conséquence de défauts organisationnels</strong> plus profonds. On distingue les <strong><span class=\"kw-def\">erreurs actives</span></strong> (au contact du patient, à effet immédiat) des <strong><span class=\"kw-def\">erreurs latentes</span></strong> (défaillances organisationnelles, non visibles au 1<sup>er</sup> abord).</p>\n\n<h4 class=\"kw-def\">Typologie de l'erreur</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Erreur par omission</span></strong> : action nécessaire non réalisée ;</li>\n  <li><strong><span class=\"kw-def\">Erreur par commission</span></strong> : action réalisée mais inutile ;</li>\n  <li><strong><span class=\"kw-def\">Erreur d'exécution</span></strong> : action mal réalisée ;</li>\n  <li><strong><span class=\"kw-def\">Violation</span></strong> : non-respect <span class=\"kw-alerte\">volontaire</span> d'une règle (&ne; erreur involontaire).</li>\n</ul>\n\n<h4 class=\"kw-def\">Facteurs favorisants (causes racines &mdash; méthode <span class=\"kw-def\">ALARM</span>)</h4>\n<ul>\n  <li><strong><span class=\"kw-etio\">Patient</span></strong> : gravité, comorbidités, difficultés de communication, vulnérabilité (âge extrême, maladie chronique) ;</li>\n  <li><strong><span class=\"kw-etio\">Tâches</span></strong> à accomplir ;</li>\n  <li><strong><span class=\"kw-etio\">Équipe</span></strong> : communication, traçabilité dans le dossier, encadrement des juniors ;</li>\n  <li><strong><span class=\"kw-etio\">Environnement de travail</span></strong> : physique (locaux, matériel) et organisationnel (effectifs, horaires) ;</li>\n  <li><strong><span class=\"kw-etio\">Organisation / management</span></strong> : remplacement du personnel, formation continue ;</li>\n  <li><strong><span class=\"kw-etio\">Contexte institutionnel</span></strong> : politiques de santé, systèmes de signalement.</li>\n</ul>\n<div class=\"callout callout-info\">La <strong><span class=\"kw-def\">violation</span></strong> se distingue de l'erreur : elle est <span class=\"kw-alerte\">volontaire</span> (routine, gain de temps, contexte d'urgence), même si elle n'est pas malveillante.</div>","frequence":0},{"id":"5-14","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Prévention : connaître la prévention des erreurs, des EIAS, la notion de barrière de sécurité","contenu":"<p>Une <strong><span class=\"kw-def\">barrière de sécurité</span></strong> est une <strong>défense en profondeur</strong> contre le risque d'erreur. Un système de sécurité efficace doit posséder les <strong><span class=\"kw-chiffre\">3 types</span> de barrières</strong> (prévention, récupération, atténuation), agencées en couches successives (modèle du &laquo; <span class=\"kw-def\">fromage suisse</span> &raquo;).</p>\n\n<h4 class=\"kw-def\">Nature des barrières</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Immatérielle</span></strong> (logique) : <span class=\"kw-clinique\">lois et réglementation</span>, consignes, recommandations, <span class=\"kw-clinique\">protocoles</span>, formation ;</li>\n  <li><strong><span class=\"kw-def\">Matérielle</span></strong> (physique) : <span class=\"kw-clinique\">détrompeur physique</span> (ex. forme spécifique des raccords de gaz médicaux).</li>\n</ul>\n\n<h4 class=\"kw-def\">Les 3 types fonctionnels</h4>\n<table >\n  <thead><tr><th>Barrière</th><th>Rôle</th><th>Exemple</th></tr></thead>\n  <tbody>\n    <tr><td><strong><span class=\"kw-def\">Prévention</span></strong></td><td>Empêcher la survenue de l'erreur</td><td><span class=\"kw-clinique\">Check-list chirurgicale</span> ; prescription informatisée avec alertes</td></tr>\n    <tr><td><strong><span class=\"kw-def\">Récupération</span></strong></td><td>Rattraper l'erreur avant tout dommage</td><td>Infirmière détectant une <span class=\"kw-etio\">allergie</span> à l'<span class=\"kw-ttt\">antibioprophylaxie</span> dans le dossier</td></tr>\n    <tr><td><strong><span class=\"kw-def\">Atténuation</span></strong></td><td>Limiter les conséquences d'une erreur non rattrapée</td><td><span class=\"kw-alerte\">Arrêt cardiaque</span> &rarr; massage + réanimation immédiats</td></tr>\n  </tbody>\n</table>\n<div class=\"callout callout-info\">La prévention passe aussi par une <strong><span class=\"kw-def\">culture positive de l'erreur</span></strong> : favoriser le <span class=\"kw-clinique\">signalement</span>, l'<span class=\"kw-clinique\">analyse</span> des EIAS et la mise en place d'actions correctrices.</div>","frequence":1},{"id":"5-15","rang":"B","rubrique":"Définition","titre":"Approche systémique : connaître la démarche de culture positive de l’erreur o N 6. L’organisation de l’exercice clinique et les méthodes qui permettent de sécuriser le parcours du patient","contenu":"<p>L'<strong><span class=\"kw-def\">approche systémique</span></strong> considère que la survenue d'un accident ne résulte pas d'une <span class=\"kw-clinique\">faute individuelle isolée</span> mais d'un <strong>enchaînement de facteurs</strong>. Elle fonde la <strong><span class=\"kw-def\">culture positive de l'erreur</span></strong>, dont le principe est la <strong><span class=\"kw-def\">non-culpabilisation</span></strong> de la personne ayant commis l'erreur (les causes sont le plus souvent <span class=\"kw-etio\">multiples</span> et <span class=\"kw-etio\">latentes</span>).</p>\n\n<h4 class=\"kw-def\">En pratique : favoriser le signalement</h4>\n<ul>\n  <li>Une <strong>charte</strong> garantit que le <strong><span class=\"kw-clinique\">signalement</span> ne sera pas sanctionné</strong> ;</li>\n  <li><strong><span class=\"kw-def\">Objectivité</span></strong> : signalement reposant sur des <span class=\"kw-clinique\">faits non interprétés</span> ;</li>\n  <li><strong><span class=\"kw-def\">Anonymat</span></strong> et <strong><span class=\"kw-def\">confidentialité</span></strong> de l'analyse ;</li>\n  <li><strong><span class=\"kw-def\">Exhaustivité</span></strong> pour identifier l'ensemble des risques.</li>\n</ul>\n\n<h4 class=\"kw-def\">Recueil des événements indésirables graves (EIG)</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Systèmes passifs</span></strong> : <span class=\"kw-etio\">volontariat</span> des professionnels (déclaration pourtant obligatoire, loi <strong><span class=\"kw-def\">HPST 2009</span></strong>) et des patients &rarr; transmis au <strong><span class=\"kw-def\">coordinateur de la gestion des risques</span></strong> (fonction obligatoire dans chaque établissement) ;</li>\n  <li><strong><span class=\"kw-def\">Systèmes actifs</span></strong> : analyse rétrospective des dossiers, <strong><span class=\"kw-def\">revues de morbi-mortalité (RMM)</span></strong>.</li>\n</ul>\n<div class=\"callout callout-danger\">&#9888; À l'inverse, la culpabilisation pousse à <span class=\"kw-alerte\">cacher les erreurs</span> et crée une <strong><span class=\"kw-alerte\">seconde victime</span></strong> : le soignant impliqué, traumatisé (sentiment d'échec, remise en question pouvant aller jusqu'au <span class=\"kw-alerte\">suicide</span>).</div>","frequence":1},{"id":"5-16","rang":"A","rubrique":"Définition","titre":"Connaître la définition du travail en équipe pluriprofessionnelle","contenu":"<p>Le <strong><span class=\"kw-def\">travail en équipe pluriprofessionnelle</span></strong> consiste, pour les professionnels de santé d'un même <span class=\"kw-etio\">territoire</span>, à <strong><span class=\"kw-clinique\">coordonner et organiser leur exercice</span></strong> afin de faciliter le <span class=\"kw-def\">parcours de soins</span> du patient. Il repose sur l'<strong><span class=\"kw-clinique\">analyse concertée</span></strong> des besoins, conformément aux <span class=\"kw-clinique\">recommandations de bonne pratique</span>, et sur la <span class=\"kw-clinique\">mise en relation</span> des différents professionnels.</p>\n\n<h4 class=\"kw-def\">Objectifs</h4>\n<ul>\n  <li>Permettre l'<strong><span class=\"kw-clinique\">échange d'information</span></strong> autour du <span class=\"kw-clinique\">dossier patient</span> ;</li>\n  <li>Faciliter la <strong><span class=\"kw-clinique\">diffusion et l'acquisition des bonnes pratiques</span></strong> ;</li>\n  <li>Améliorer la prise en charge &mdash; <span class=\"kw-clinique\">prévention</span>, <span class=\"kw-clinique\">soins</span>, <span class=\"kw-clinique\">suivi</span> &mdash; surtout chez les patients <span class=\"kw-etio\">pluripathologiques</span>.</li>\n</ul>\n\n<h4 class=\"kw-def\">Compétences mobilisées</h4>\n<p>À la fois <strong><span class=\"kw-def\">techniques</span></strong> et <strong><span class=\"kw-def\">non techniques</span></strong> : la coordination entre corps de métiers sécurise la prise en charge, notamment en <strong><span class=\"kw-alerte\">situation d'urgence</span></strong> (<span class=\"kw-clinique\">bloc opératoire</span>, <span class=\"kw-clinique\">réanimation</span>).</p>\n\n<div class=\"callout callout-info\">Selon la <strong><span class=\"kw-def\">HAS</span></strong>, un <strong><span class=\"kw-chiffre\">tiers des événements indésirables graves</span></strong> pourraient être évités par une meilleure coordination et communication des équipes. Le travail d'équipe est ainsi une <strong><span class=\"kw-def\">barrière de sécurité</span></strong>, un facteur de <span class=\"kw-clinique\">qualité</span> des soins et de <span class=\"kw-clinique\">bien-être au travail</span>.</div>\n<p class=\"obj-source\"><em>Complété depuis le Collège.</em></p>","frequence":0},{"id":"5-17","rang":"A","rubrique":"Définition","titre":"Connaître les principaux dispositifs du travail en équipe pluridisciplinaire","contenu":"<p>Les <strong><span class=\"kw-def\">dispositifs du travail en équipe</span></strong> regroupent des professionnels (médicaux, auxiliaires médicaux, pharmaciens) autour d'un <strong><span class=\"kw-clinique\">projet de soins commun</span></strong>, en assurant la <span class=\"kw-clinique\">continuité des soins</span>. On distingue les <strong>structures de regroupement</strong> et les <strong>méthodes de sécurisation</strong>.</p>\n\n<h4 class=\"kw-def\">Structures de regroupement (ambulatoire)</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Maison de santé pluriprofessionnelle</span></strong> et <strong><span class=\"kw-def\">centre de santé</span></strong> : regroupement dans un <span class=\"kw-clinique\">lieu unique</span> ;</li>\n  <li><strong><span class=\"kw-def\">Pôle de santé</span></strong> : regroupement <span class=\"kw-clinique\">virtuel</span> (sans lieu unique).</li>\n</ul>\n\n<h4 class=\"kw-def\">Méthodes de sécurisation du parcours</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Protocoles pluriprofessionnels</span></strong> (<span class=\"kw-clinique\">exercice coordonné et protocolé</span>) ;</li>\n  <li><strong><span class=\"kw-def\">Réunions de concertation pluridisciplinaire</span></strong> (RCP) ;</li>\n  <li><strong><span class=\"kw-def\">Listes de vérification</span></strong> (check-lists) ;</li>\n  <li><strong><span class=\"kw-def\">Réunions de morbi-mortalité</span></strong> (RMM).</li>\n</ul>\n\n<div class=\"callout callout-info\">Ces dispositifs existent <strong>en ambulatoire</strong> comme <strong>en milieu hospitalier</strong> ; ils visent à améliorer la <span class=\"kw-clinique\">coordination</span>, la <span class=\"kw-clinique\">sécurité des soins</span> et l'<span class=\"kw-clinique\">harmonisation des pratiques</span>.</div>\n<p class=\"obj-source\"><em>Complété depuis le Collège.</em></p>","frequence":0},{"id":"5-18","rang":"A","rubrique":"Définition","titre":"Connaître la définition du parcours de soins","contenu":"<p>La <strong><span class=\"kw-def\">démarche de parcours de soins</span></strong> consiste à <strong><span class=\"kw-clinique\">organiser et coordonner</span></strong> le <strong><span class=\"kw-def\">juste enchaînement</span></strong>, <strong><span class=\"kw-clinique\">au bon moment</span></strong>, des <span class=\"kw-clinique\">compétences professionnelles</span> (médicales, soignantes et sociales) autour du patient. Elle répond à la complexité des prises en charge des <span class=\"kw-etio\">maladies chroniques</span>, sur une <span class=\"kw-clinique\">longue durée</span>.</p>\n\n<h4 class=\"kw-def\">Sur quoi elle s'appuie</h4>\n<ul>\n  <li>Les <strong><span class=\"kw-clinique\">bonnes pratiques</span></strong> de chaque professionnel ;</li>\n  <li>Des actions d'<strong><span class=\"kw-clinique\">anticipation</span></strong>, de <strong><span class=\"kw-clinique\">coordination</span></strong> et d'<strong><span class=\"kw-clinique\">échange d'informations</span></strong> entre tous les acteurs impliqués.</li>\n</ul>\n\n<h4 class=\"kw-def\">Les trois niveaux de recours</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Soins primaires</span></strong> : <span class=\"kw-clinique\">médecine générale</span> ;</li>\n  <li><strong><span class=\"kw-def\">Soins secondaires</span></strong> : <span class=\"kw-clinique\">médecine spécialisée</span> (ville ou hôpital) ;</li>\n  <li><strong><span class=\"kw-def\">Soins tertiaires</span></strong> : <span class=\"kw-clinique\">médecine de haute technologie</span> (hôpitaux universitaires).</li>\n</ul>\n\n<div class=\"callout callout-info\">Finalité : assurer le <strong>juste soin au bon moment</strong> grâce à la <span class=\"kw-clinique\">continuité</span> et à la <span class=\"kw-clinique\">coordination</span> de la prise en charge tout au long du parcours.</div>\n<p class=\"obj-source\"><em>Complété depuis le Collège.</em></p>","frequence":0},{"id":"5-19","rang":"B","rubrique":"Définition","titre":"Protocoles pluriprofessionnels : connaître la définition, les objectifs et les enjeux des protocoles pluriprofessionnels","contenu":"<p>Un <strong><span class=\"kw-def\">protocole pluriprofessionnel</span></strong> est l'expression d'un <strong><span class=\"kw-def\">consensus local et documenté</span></strong> concernant la prise en charge pluriprofessionnelle d'un <span class=\"kw-clinique\">problème identifié</span> par une équipe. Il associe des compétences <span class=\"kw-clinique\">médicales</span>, <span class=\"kw-clinique\">soignantes</span> et <span class=\"kw-clinique\">médico-sociales</span> pour une maladie aiguë ou chronique.</p>\n\n<h4 class=\"kw-def\">Élaboration et contenu</h4>\n<ul>\n  <li>Travail en <strong>groupe restreint</strong> : au moins un représentant par <span class=\"kw-clinique\">profession impliquée</span> ;</li>\n  <li>S'appuie sur la <span class=\"kw-clinique\">littérature</span>, le <span class=\"kw-clinique\">travail en équipe</span> et la <span class=\"kw-clinique\">gestion des risques</span> (guide <span class=\"kw-def\">HAS</span>) ;</li>\n  <li>Contient des <span class=\"kw-clinique\">messages clés</span>, aide-mémoire, <span class=\"kw-clinique\">check-lists</span> et aides à la prescription.</li>\n</ul>\n\n<h4 class=\"kw-def\">Enjeux</h4>\n<ul>\n  <li>Faciliter le <strong><span class=\"kw-clinique\">travail en équipe</span></strong> ;</li>\n  <li>Améliorer l'<span class=\"kw-clinique\">articulation entre soins de 1<sup>er</sup> et 2<sup>e</sup> recours</span> ;</li>\n  <li><strong><span class=\"kw-clinique\">Harmoniser les pratiques</span></strong> professionnelles ;</li>\n  <li>Alimenter le <span class=\"kw-clinique\">dossier patient partagé</span> ;</li>\n  <li>Valider le <strong><span class=\"kw-def\">développement professionnel continu (DPC)</span></strong>.</li>\n</ul>\n<div class=\"callout callout-info\">Un enjeu associé est le <strong><span class=\"kw-def\">transfert de tâche</span></strong> entre professionnels, sécurisé par le cadre du protocole.</div>\n<p class=\"obj-source\"><em>Complété depuis le Collège.</em></p>","frequence":0},{"id":"5-20","rang":"A","rubrique":"Définition","titre":"Réunions de concertation pluridisciplinaire (RCP) : connaître les principes et les objectifs d’une RCP","contenu":"<p>La <strong><span class=\"kw-def\">réunion de concertation pluridisciplinaire</span></strong> (RCP) est une <strong><span class=\"kw-def\">réunion collégiale</span></strong> regroupant des professionnels de <strong><span class=\"kw-clinique\">disciplines différentes</span></strong>, dont les compétences sont indispensables pour décider <strong><span class=\"kw-clinique\">collégialement</span></strong> de la <strong><span class=\"kw-clinique\">meilleure prise en charge</span></strong> du patient selon l'<span class=\"kw-clinique\">état de la science</span> du moment.</p>\n\n<h4 class=\"kw-def\">Principes</h4>\n<ul>\n  <li>Le <strong><span class=\"kw-clinique\">dossier de chaque patient</span></strong> est présenté ; la prise en charge est définie <strong><span class=\"kw-clinique\">collectivement</span></strong> sur la base de <span class=\"kw-clinique\">référentiels</span> ;</li>\n  <li>Un <strong><span class=\"kw-clinique\">avis de RCP</span></strong> est rédigé, puis <span class=\"kw-clinique\">soumis et expliqué au patient</span> ;</li>\n  <li>Validité : présence d'<strong><span class=\"kw-chiffre\">au moins 3 médecins</span></strong> de <span class=\"kw-clinique\">spécialités différentes</span> (sinon, redprésenter le dossier avec le spécialiste manquant).</li>\n</ul>\n\n<h4 class=\"kw-def\">Objectifs</h4>\n<ul>\n  <li>Garantir une décision <strong>collégiale et pertinente</strong>, conforme aux référentiels ;</li>\n  <li>Initialement développée en <strong><span class=\"kw-etio\">oncologie</span></strong> (<span class=\"kw-etio\">cancer</span>), extensible aux <span class=\"kw-etio\">maladies à prise en charge complexe</span> ;</li>\n  <li>La participation régulière valide le <strong><span class=\"kw-def\">DPC</span></strong>.</li>\n</ul>\n<p class=\"obj-source\"><em>Complété depuis le Collège.</em></p>","frequence":0},{"id":"5-21","rang":"A","rubrique":"Définition","titre":"Listes de vérification ou check-lists : connaître les principes et les objectifs des listes de vérification","contenu":"<p>La <strong><span class=\"kw-def\">liste de vérification</span></strong> (check-list) est un outil de sécurité <span class=\"kw-etio\">inspiré de l'aéronautique</span>. Au bloc opératoire, elle est un <strong><span class=\"kw-def\">outil de communication</span></strong> et de <strong><span class=\"kw-clinique\">vérification croisée</span></strong> entre les membres de l'équipe.</p>\n\n<h4 class=\"kw-def\">Principe : 3 temps de pause</h4>\n<ul>\n  <li><strong><span class=\"kw-clinique\">Avant induction anesthésique</span></strong> ;</li>\n  <li><strong><span class=\"kw-clinique\">Avant incision</span></strong> (&laquo; time-out &raquo;) ;</li>\n  <li><strong><span class=\"kw-clinique\">Après l'intervention</span></strong> (avant la sortie de salle).</li>\n</ul>\n<p>Elle permet d'<strong>interrompre momentanément</strong> la procédure avant qu'un problème ne survienne (manquement à un item).</p>\n\n<h4 class=\"kw-def\">Objectifs</h4>\n<ul>\n  <li><strong><span class=\"kw-clinique\">Normaliser les échanges</span></strong> et faciliter la communication dans l'équipe ;</li>\n  <li><strong>Vérifier</strong> l'<span class=\"kw-clinique\">identité du patient</span>, le <span class=\"kw-clinique\">type d'intervention</span>, le <strong><span class=\"kw-alerte\">site opératoire</span></strong>, le matériel et les risques ;</li>\n  <li>Prévenir les <span class=\"kw-clinique\">événements indésirables</span>.</li>\n</ul>\n<div class=\"callout callout-info\">La check-list &laquo; <strong><span class=\"kw-def\">Sécurité du patient au bloc opératoire</span></strong> &raquo; a démontré une <strong><span class=\"kw-clinique\">diminution de la morbimortalité</span> postopératoire</strong>. La <span class=\"kw-def\">HAS</span> a décliné le principe à d'autres activités interventionnelles (<span class=\"kw-imagerie\">endoscopie</span>, radiologie interventionnelle, chimiothérapie...).</div>\n<p class=\"obj-source\"><em>Complété depuis le Collège.</em></p>","frequence":0},{"id":"5-22","rang":"A","rubrique":"Définition","titre":"Réunions de morbi-mortalité (RMM) : connaître les principes et les objectifs d’une RMM","contenu":"<p>La <strong><span class=\"kw-def\">réunion de morbi-mortalité</span></strong> (RMM) est une <strong><span class=\"kw-def\">analyse collective et rétrospective</span></strong> de cas marqués par un <strong><span class=\"kw-def\">événement indésirable associé aux soins (EIAS)</span></strong> : <span class=\"kw-clinique\">décès</span>, <span class=\"kw-clinique\">complication</span>, mais aussi tout événement qui <strong>aurait pu</strong> causer un dommage (presque-accident).</p>\n\n<h4 class=\"kw-def\">Objectif</h4>\n<p>Mettre en œuvre des actions de <strong><span class=\"kw-def\">prévention</span></strong>, de <strong><span class=\"kw-def\">récupération</span></strong> ou d'<strong><span class=\"kw-def\">atténuation</span></strong> pour éviter la récidive.</p>\n\n<h4 class=\"kw-def\">Principes de l'analyse</h4>\n<ul>\n  <li>Dans un <strong><span class=\"kw-clinique\">climat de confiance</span></strong> et constructif (non culpabilisant) ;</li>\n  <li><strong><span class=\"kw-clinique\">Globale et systémique</span></strong> : prend en compte les composantes <span class=\"kw-etio\">organisationnelles</span>, <span class=\"kw-etio\">techniques</span> et <span class=\"kw-etio\">humaines</span> ;</li>\n  <li>Dépasse la seule réflexion centrée sur l'<span class=\"kw-clinique\">individu</span>.</li>\n</ul>\n<div class=\"callout callout-info\">Réalisée avec un temps explicite de formation, la RMM est une méthode validante de <strong><span class=\"kw-def\">DPC</span></strong>.</div>\n<p class=\"obj-source\"><em>Complété depuis le Collège.</em></p>","frequence":0},{"id":"5-23","rang":"A","rubrique":"Prise en charge","titre":"Connaître l’organisation des urgences (SAMU, SMUR, structures d’urgences et spécialisées) et la gestion d’un appel d’urgence","contenu":"<p>La <strong><span class=\"kw-def\">régulation médicale</span></strong> est un <strong>acte médical de télémédecine</strong> pratiqué au téléphone par des <strong><span class=\"kw-def\">médecins régulateurs</span></strong> de l'<span class=\"kw-def\">aide médicale urgente (AMU)</span> et des médecins régulateurs généralistes. Elle est le point d'entrée de la <strong><span class=\"kw-clinique\">gestion d'un appel d'urgence</span></strong>.</p>\n\n<h4 class=\"kw-def\">Le SAMU-Centre 15</h4>\n<ul>\n  <li>Structure dédiée : <strong><span class=\"kw-def\">SAMU-Centre 15</span></strong> (centre de réception et de régulation des appels, <span class=\"kw-def\">CRRA</span>), implantée au cœur du secteur des urgences d'un hôpital ;</li>\n  <li>Le <strong><span class=\"kw-clinique\">médecin régulateur</span></strong> détermine et déclenche la <strong><span class=\"kw-clinique\">réponse la mieux adaptée</span></strong>, puis oriente si besoin vers l'<span class=\"kw-clinique\">unité d'hospitalisation appropriée</span>.</li>\n</ul>\n\n<h4 class=\"kw-def\">Réponses possibles à l'appel</h4>\n<ul>\n  <li><strong><span class=\"kw-clinique\">Simple conseil</span></strong> médical ;</li>\n  <li>Envoi du <strong><span class=\"kw-clinique\">médecin généraliste de permanence</span></strong> (PDSA) ;</li>\n  <li>Envoi d'une <strong><span class=\"kw-clinique\">ambulance</span></strong> ;</li>\n  <li>Intervention du <strong><span class=\"kw-def\">SMUR</span></strong> (service mobile d'urgence et de réanimation).</li>\n</ul>\n\n<div class=\"callout callout-info\">Exemple : devant une <strong><span class=\"kw-alerte\">douleur thoracique</span></strong> évoquant un <span class=\"kw-clinique\">syndrome coronarien aigu</span>, le SAMU-Centre 15 envoie immédiatement un <strong><span class=\"kw-def\">SMUR</span></strong> et oriente directement le patient vers l'<strong><span class=\"kw-clinique\">unité de coronarographie</span></strong> (coronarographiste d'astreinte mobilisé avant l'arrivée). La régulation optimise l'accès au <strong>juste soin</strong>.</div>\n<p class=\"obj-source\"><em>Complété depuis le Collège.</em></p>","frequence":0}],"astuces":[],"strategie":{},"cards":[{"i":"02bcfc874646","n":5,"o":"5-1","u":"Définition","t":"Connaître la définition de la responsabilité sanction/indemnisation","q":"Quels sont les différents types de responsabilité sanction en médecine et leurs conséquences ?","a":"<ul><li>La <strong>responsabilité pénale</strong>: elle peut entraîner une <strong>amende</strong>, une <strong>peine d'emprisonnement</strong> ou une <strong>interdiction d'exercice</strong>.</li><li>La <strong>responsabilité disciplinaire (ordinale)</strong>: elle peut aboutir à un <strong>avertissement</strong>, un <strong>blâme</strong>, une <strong>interdiction temporaire d'exercer</strong>, ou une <strong>radiation</strong>.</li></ul>"},{"i":"4f34aae2ac93","n":5,"o":"5-1","u":"Définition","t":"Connaître la définition de la responsabilité sanction/indemnisation","q":"Quelle est la finalité principale de la responsabilité indemnisation en médecine ?","a":"<p>La finalité de la responsabilité indemnisation est de <strong>réparer le préjudice subi par la victime</strong>, généralement par l'attribution de <strong>dommages et intérêts</strong>.</p>"},{"i":"531ebfb3ff9e","n":5,"o":"5-1","u":"Définition","t":"Connaître la définition de la responsabilité sanction/indemnisation","q":"Quelle est la finalité principale de la responsabilité sanction en médecine ?","a":"<p>La finalité de la responsabilité sanction est de <strong>punir un comportement médical réprouvé par la société</strong>. Elle n'a pas pour but d'indemniser le préjudice subi par la victime.</p>"},{"i":"92bdf043e7db","n":5,"o":"5-1","u":"Définition","t":"Connaître la définition de la responsabilité sanction/indemnisation","q":"Les différentes formes de responsabilités médicales sont-elles indépendantes les unes des autres ?","a":"<p>Oui, les différentes responsabilités médicales (civile, administrative, pénale, disciplinaire) sont <strong>indépendantes et peuvent se cumuler</strong> pour un même fait.</p>"},{"i":"f3cac189269b","n":5,"o":"5-1","u":"Définition","t":"Connaître la définition de la responsabilité sanction/indemnisation","q":"Quels sont les différents types de responsabilité indemnisation en médecine et qui est concerné ?","a":"<ul><li>La <strong>responsabilité civile</strong>: elle concerne les <strong>médecins libéraux</strong> et les <strong>établissements de santé privés</strong>, et est jugée par le tribunal judiciaire.</li><li>La <strong>responsabilité administrative</strong>: elle concerne les <strong>médecins salariés du service public hospitalier</strong>, et est jugée par le tribunal administratif.</li></ul>"},{"i":"34d5e85d44c4","n":5,"o":"5-10","u":"Définition","t":"Connaître la définition de l’infection nosocomiale","q":"Quel est le régime d'indemnisation applicable aux infections nosocomiales en fonction de l'acteur concerné ?","a":"<ul><li>Pour un <strong>professionnel libéral</strong> : la responsabilité nécessite une <strong>faute prouvée</strong> par le patient (faute + dommage + lien de causalité).</li><li>Pour un <strong>établissement de santé</strong> : il existe une <strong>présomption de faute</strong>. L'établissement doit prouver une cause étrangère pour s'exonérer.</li><li>L'<strong>ONIAM</strong> (Office National d'Indemnisation des Accidents Médicaux) intervient au titre de la solidarité nationale si l'<strong>AIPP (atteinte à l'intégrité physique et psychique) est supérieure à 25 %</strong> ou en cas de <strong>décès</strong>.</li></ul>"},{"i":"7498665cf38e","n":5,"o":"5-10","u":"Définition","t":"Connaître la définition de l’infection nosocomiale","q":"Quels sont les délais de survenue de référence pour la définition d'une infection nosocomiale ?","a":"<ul><li><strong>Plus de 48 heures</strong> après l'admission, si le statut infectieux à l'entrée est inconnu.</li><li>Jusqu'à <strong>30 jours</strong> après une intervention chirurgicale (pour une infection du site opératoire).</li><li>Jusqu'à <strong>1 an</strong> en cas de pose de matériel prothétique ou d'implant.</li></ul>"},{"i":"97171122d967","n":5,"o":"5-10","u":"Définition","t":"Connaître la définition de l’infection nosocomiale","q":"Quand l'ONIAM peut-il exercer un recours subrogatoire concernant une infection nosocomiale ?","a":"<p>L'ONIAM peut exercer un recours subrogatoire contre l'établissement de santé pour les infections survenues <strong>après le 1er janvier 2003</strong>, s'il parvient à établir un <strong>manquement caractérisé</strong> de l'établissement à ses obligations réglementaires.</p>"},{"i":"9813659c08d1","n":5,"o":"5-10","u":"Définition","t":"Connaître la définition de l’infection nosocomiale","q":"Quelle est la définition d'une infection nosocomiale ?","a":"<p>L'infection nosocomiale est une <strong>infection associée aux soins (IAS)</strong>, acquise au sein d'un établissement de santé. Elle est caractérisée par son absence à l'admission du patient et son apparition au décours de la prise en charge.</p>"},{"i":"d33e5eae6be7","n":5,"o":"5-10","u":"Définition","t":"Connaître la définition de l’infection nosocomiale","q":"Comment différencie-t-on une infection nosocomiale d'une infection associée aux soins (IAS) ?","a":"<p>L'<strong>infection associée aux soins (IAS)</strong> est un concept plus large qui englobe toute infection survenant au cours du parcours de soins, y compris en ville. L'<strong>infection nosocomiale</strong> en est un sous-ensemble spécifique, désignant une IAS contractée au cours d'une prise en charge <strong>hospitalière</strong>.</p>"},{"i":"2bd4e44eef2c","n":5,"o":"5-11","u":"Définition","t":"Connaître la définition de l’aléa thérapeutique","q":"Quelle est la définition de l'aléa thérapeutique ?","a":"<p>L'aléa thérapeutique est un événement indésirable survenant lors d'une action de soins conforme, <strong>sans erreur ni faute</strong>. Il correspond à la réalisation d'un <strong>risque inhérent à l'acte de soin</strong> et sa caractéristique majeure est son <strong>inévitabilité</strong>.</p>"},{"i":"3b5868bde4f4","n":5,"o":"5-11","u":"Définition","t":"Connaître la définition de l’aléa thérapeutique","q":"Quelles sont les conditions pour qu'un aléa thérapeutique soit indemnisé par l'ONIAM au titre de la solidarité nationale ?","a":"<ul><li>Des conséquences <strong>anormales</strong> : soit un dommage plus grave que l'évolution naturelle de la maladie, soit de survenue peu probable (<strong>&lt; 5 %</strong>).</li><li>Un seuil de gravité : une <strong>AIPP &gt; 24 %</strong>, ou un ATAP/DFT <strong>&ge; 50 %</strong> pendant <strong>&ge; 6 mois</strong>.</li></ul>"},{"i":"8398331d80bc","n":5,"o":"5-11","u":"Définition","t":"Connaître la définition de l’aléa thérapeutique","q":"Quelles formes d'événements l'aléa thérapeutique recouvre-t-il, lorsqu'ils surviennent sans responsabilité du professionnel ou de l'établissement ?","a":"<ul><li>Un <strong>accident médical</strong>.</li><li>Une <strong>affection iatrogène</strong>.</li><li>Une <strong>infection nosocomiale</strong>.</li></ul>"},{"i":"d121ad5570a9","n":5,"o":"5-11","u":"Définition","t":"Connaître la définition de l’aléa thérapeutique","q":"Quels sont les actes exclus du régime amiable d'indemnisation de l'aléa thérapeutique par l'ONIAM ?","a":"<ul><li>La <strong>chirurgie esthétique</strong>.</li><li>L'<strong>accouchement par voie basse</strong>.</li></ul>"},{"i":"122aa5cb50f2","n":5,"o":"5-13","u":"Définition","t":"Facteurs humains : connaître la notion d’erreur humaine (typologie et facteurs favorisants)","q":"Quelle est la particularité d'une violation par rapport aux autres types d'erreurs ?","a":"<p>Une violation se distingue par son caractère <strong>volontaire</strong>. Elle correspond au non-respect intentionnel d'une règle, souvent motivé par la routine, un gain de temps, ou un contexte d'urgence, même si elle n'est pas malveillante.</p>"},{"i":"361607b4ac6c","n":5,"o":"5-13","u":"Définition","t":"Facteurs humains : connaître la notion d’erreur humaine (typologie et facteurs favorisants)","q":"Quelles sont les différentes typologies d'erreurs humaines ?","a":"<ul><li><strong>Erreur par omission</strong> : une action nécessaire n'est pas réalisée.</li><li><strong>Erreur par commission</strong> : une action est réalisée mais s'avère inutile ou inadaptée.</li><li><strong>Erreur d'exécution</strong> : une action est mal réalisée.</li><li><strong>Violation</strong> : un non-respect volontaire d'une règle (se distingue de l'erreur involontaire).</li></ul>"},{"i":"5646f1440f40","n":5,"o":"5-13","u":"Définition","t":"Facteurs humains : connaître la notion d’erreur humaine (typologie et facteurs favorisants)","q":"Comment la notion d'erreur humaine est-elle conceptualisée dans le modèle de Reason (modèle du « fromage suisse ») ?","a":"<p>Selon le modèle de Reason, l'erreur humaine est rarement isolée. Elle est le plus souvent la conséquence de <strong>défauts organisationnels plus profonds</strong>, les erreurs actives étant la manifestation en surface de ces erreurs latentes.</p>"},{"i":"682190d6f9f8","n":5,"o":"5-13","u":"Définition","t":"Facteurs humains : connaître la notion d’erreur humaine (typologie et facteurs favorisants)","q":"Quels sont les facteurs favorisants (causes racines) des erreurs humaines en santé selon la méthode ALARM ?","a":"<ul><li>Liés au <strong>patient</strong> : gravité, comorbidités, difficultés de communication, vulnérabilité (âge extrême, maladie chronique).</li><li>Liés aux <strong>tâches à accomplir</strong>.</li><li>Liés à l'<strong>équipe</strong> : communication, traçabilité dans le dossier, encadrement des juniors.</li><li>Liés à l'<strong>environnement de travail</strong> : physique (locaux, matériel) et organisationnel (effectifs, horaires).</li><li>Liés à l'<strong>organisation / management</strong> : remplacement du personnel, formation continue.</li><li>Liés au <strong>contexte institutionnel</strong> : politiques de santé, systèmes de signalement.</li></ul>"},{"i":"a4f0fc634889","n":5,"o":"5-13","u":"Définition","t":"Facteurs humains : connaître la notion d’erreur humaine (typologie et facteurs favorisants)","q":"Quelle est la différence entre une erreur active et une erreur latente en santé ?","a":"<ul><li>Une <strong>erreur active</strong> est une erreur survenant au contact du patient, avec un effet immédiat et direct.</li><li>Une <strong>erreur latente</strong> est une défaillance organisationnelle qui n'est pas immédiatement visible mais favorise la survenue d'erreurs actives.</li></ul>"},{"i":"1b038f21808a","n":5,"o":"5-16","u":"Définition","t":"Connaître la définition du travail en équipe pluriprofessionnelle","q":"Quelle est la définition du travail en équipe pluriprofessionnelle en santé ?","a":"<p>Le travail en équipe pluriprofessionnelle consiste à <strong>coordonner et organiser l'exercice des professionnels de santé d'un même territoire</strong> afin de faciliter le parcours de soins du patient. Il repose sur l'<strong>analyse concertée des besoins</strong> et la <strong>mise en relation des différents professionnels</strong>, conformément aux recommandations de bonne pratique.</p>"},{"i":"abdc32f074a2","n":5,"o":"5-16","u":"Définition","t":"Connaître la définition du travail en équipe pluriprofessionnelle","q":"Quelles sont les compétences mobilisées et les bénéfices du travail en équipe pluriprofessionnelle ?","a":"<p>Il mobilise des compétences à la fois <strong>techniques et non techniques</strong>. La coordination entre corps de métiers <strong>sécurise la prise en charge</strong>, en particulier en situation d'urgence (bloc opératoire, réanimation).</p><p>Selon la HAS, un tiers des événements indésirables graves pourraient être évités par une meilleure coordination et communication. Le travail d'équipe est ainsi une <strong>barrière de sécurité</strong>, un <strong>facteur de qualité des soins</strong> et de <strong>bien-être au travail</strong>.</p>"},{"i":"e4f89b71fb93","n":5,"o":"5-16","u":"Définition","t":"Connaître la définition du travail en équipe pluriprofessionnelle","q":"Quels sont les objectifs du travail en équipe pluriprofessionnelle ?","a":"<ul><li>Permettre l'<strong>échange d'informations</strong> autour du dossier patient.</li><li>Faciliter la <strong>diffusion et l'acquisition des bonnes pratiques</strong>.</li><li>Améliorer la <strong>prise en charge</strong> (prévention, soins, suivi), notamment chez les patients pluripathologiques.</li></ul>"},{"i":"4215e9db4809","n":5,"o":"5-17","u":"Définition","t":"Connaître les principaux dispositifs du travail en équipe pluridisciplinaire","q":"Quelles sont les méthodes de sécurisation du parcours de soins mises en place dans le cadre du travail en équipe pluriprofessionnelle ?","a":"<ul><li>Les <strong>protocoles pluriprofessionnels</strong>, encourageant l'exercice coordonné et protocolisé.</li><li>Les <strong>Réunions de Concertation Pluridisciplinaire (RCP)</strong>.</li><li>Les <strong>listes de vérification (check-lists)</strong>.</li><li>Les <strong>Réunions de Morbi-Mortalité (RMM)</strong>.</li></ul>"},{"i":"431f6bcbca91","n":5,"o":"5-17","u":"Définition","t":"Connaître les principaux dispositifs du travail en équipe pluridisciplinaire","q":"Quels sont les principaux types de structures de regroupement en ambulatoire pour le travail en équipe pluriprofessionnelle ?","a":"<ul><li>La <strong>Maison de santé pluriprofessionnelle</strong> et le <strong>Centre de santé</strong> : regroupement des professionnels dans un <strong>lieu unique</strong>.</li><li>Le <strong>Pôle de santé</strong> : regroupement des professionnels de manière <strong>virtuelle</strong>, sans lieu unique.</li></ul>"},{"i":"654c7f714043","n":5,"o":"5-17","u":"Définition","t":"Connaître les principaux dispositifs du travail en équipe pluridisciplinaire","q":"Quelle est la définition des dispositifs du travail en équipe pluriprofessionnelle en santé ?","a":"<p>Ces dispositifs regroupent des <strong>professionnels de santé variés</strong> (médicaux, auxiliaires médicaux, pharmaciens) autour d'un <strong>projet de soins commun</strong>, dans le but d'assurer la <strong>continuité des soins</strong>. Ils visent à améliorer la <strong>coordination</strong>, la <strong>sécurité des soins</strong> et l'<strong>harmonisation des pratiques</strong>.</p>"},{"i":"2ae5eb08da13","n":5,"o":"5-18","u":"Définition","t":"Connaître la définition du parcours de soins","q":"À quelle problématique majeure la démarche de parcours de soins tente-t-elle de répondre ?","a":"<p>Elle répond à la <strong>complexité des prises en charge des maladies chroniques</strong>, sur une <strong>longue durée</strong>.</p>"},{"i":"3acc01e1bdfc","n":5,"o":"5-18","u":"Définition","t":"Connaître la définition du parcours de soins","q":"Quels sont les trois niveaux de recours des soins dans le cadre du parcours de soins ?","a":"<ul><li><strong>Soins primaires</strong> : médecine générale.</li><li><strong>Soins secondaires</strong> : médecine spécialisée (ville ou hôpital).</li><li><strong>Soins tertiaires</strong> : médecine de haute technologie (hôpitaux universitaires).</li></ul>"},{"i":"43a0ebd43435","n":5,"o":"5-18","u":"Définition","t":"Connaître la définition du parcours de soins","q":"Quelle est la définition de la démarche de parcours de soins ?","a":"<p>La démarche de parcours de soins consiste à organiser et coordonner le <strong>juste enchaînement</strong>, au <strong>bon moment</strong>, des compétences professionnelles (médicales, soignantes et sociales) <strong>autour du patient</strong>.</p>"},{"i":"a172bdf93008","n":5,"o":"5-18","u":"Définition","t":"Connaître la définition du parcours de soins","q":"Sur quels éléments s'appuie la démarche de parcours de soins pour sa mise en œuvre ?","a":"<ul><li>Les <strong>bonnes pratiques</strong> de chaque professionnel.</li><li>Des actions d'<strong>anticipation</strong>, de <strong>coordination</strong> et d'<strong>échange d'informations</strong> entre tous les acteurs impliqués.</li></ul>"},{"i":"e777afde146c","n":5,"o":"5-18","u":"Définition","t":"Connaître la définition du parcours de soins","q":"Quelle est la finalité principale de la démarche de parcours de soins ?","a":"<p>La finalité est d'assurer le <strong>juste soin au bon moment</strong> grâce à la <strong>continuité</strong> et à la <strong>coordination</strong> de la prise en charge tout au long du parcours.</p>"},{"i":"359cb5cec0c9","n":5,"o":"5-2","u":"Définition","t":"Connaître la définition de la responsabilité pénale","q":"Quelle est la fonction principale de la responsabilité pénale en médecine ?","a":"<p>La responsabilité pénale a une fonction <strong>répressive</strong>. Elle vise à <strong>sanctionner un comportement</strong> réprouvé par la société, qui doit être prévu par le Code pénal. Elle ne permet pas la réparation directe du dommage subi.</p>"},{"i":"4a98a9e8534a","n":5,"o":"5-2","u":"Définition","t":"Connaître la définition de la responsabilité pénale","q":"Quelles sont les infractions pénales spécifiques à l'exercice médical ?","a":"<p>Les infractions propres à l'exercice médical incluent :</p><ul><li>La violation d'un devoir d'humanisme (ex: <strong>faux certificats</strong>, <strong>violation du secret professionnel</strong>, <strong>non-assistance à personne en péril</strong>).</li><li>L'<strong>homicide ou les blessures involontaires</strong>, exigeant un lien de causalité entre la faute et le dommage (direct ou indirect si faute qualifiée).</li><li>Plus rarement, l'homicide ou les blessures volontaires (ex: <strong>euthanasie</strong>, certains cas de défaut de consentement ou d'actes hors conditions légales comme l'IVG hors délais).</li></ul><p>Il est important de noter que le <strong>défaut d'information du patient n'est PAS une infraction pénale</strong>, mais relève de la responsabilité civile.</p>"},{"i":"5ff03d5ee5f3","n":5,"o":"5-2","u":"Définition","t":"Connaître la définition de la responsabilité pénale","q":"Qui peut être visé par une responsabilité pénale en milieu médical et par qui sont engagées les poursuites ?","a":"<p>La responsabilité pénale est toujours <strong>personnelle</strong>, concernant tous les médecins, y compris les internes, quel que soit leur statut. Elle peut aussi viser les <strong>établissements de santé</strong> en tant que personnes morales. Les poursuites sont engagées par le <strong>procureur de la République</strong>.</p>"},{"i":"d863e08cec6a","n":5,"o":"5-2","u":"Définition","t":"Connaître la définition de la responsabilité pénale","q":"Quelles sont les catégories d'infractions pénales et quelles sont les infractions les plus souvent reprochées aux médecins ?","a":"<p>Il existe 3 catégories d'infractions :</p><ul><li>Les <strong>contraventions</strong>, jugées par le Tribunal de police, sanctionnées par une amende.</li><li>Les <strong>délits</strong>, jugés par le Tribunal correctionnel, sanctionnés par un emprisonnement et/ou une amende.</li><li>Les <strong>crimes</strong>, jugés par la Cour d'assises, sanctionnés par une réclusion criminelle.</li></ul><p>Les infractions le plus souvent reprochées aux médecins relèvent généralement des <strong>délits</strong> (Tribunal correctionnel) et concernent majoritairement l'<strong>homicide ou les blessures involontaires</strong>.</p>"},{"i":"483078e3ab29","n":5,"o":"5-20","u":"Définition","t":"Réunions de concertation pluridisciplinaire (RCP) : connaître les principes et les objectifs d’une RCP","q":"Qu'est-ce qu'une Réunion de Concertation Pluridisciplinaire (RCP) ?","a":"<p>Une RCP est une <strong>réunion collégiale</strong> de professionnels de santé de <strong>disciplines différentes</strong>. L'objectif est de décider collectivement de la <strong>meilleure prise en charge</strong> pour un patient, selon l'état des connaissances scientifiques actuelles.</p>"},{"i":"a53f39cd7d11","n":5,"o":"5-20","u":"Définition","t":"Réunions de concertation pluridisciplinaire (RCP) : connaître les principes et les objectifs d’une RCP","q":"Quels sont les principes de fonctionnement d'une Réunion de Concertation Pluridisciplinaire (RCP) ?","a":"<ul><li>Le <strong>dossier de chaque patient</strong> est présenté.</li><li>La prise en charge est définie <strong>collectivement</strong>, en se basant sur des <strong>référentiels</strong> validés.</li><li>Un <strong>avis de RCP</strong> est rédigé, puis <strong>soumis et expliqué au patient</strong>.</li><li>Pour être valide, une RCP doit réunir au moins <strong>3 médecins de spécialités différentes</strong>. Si ce n'est pas le cas, le dossier doit être représenté avec le spécialiste manquant.</li></ul>"},{"i":"d4daf8504ef3","n":5,"o":"5-20","u":"Définition","t":"Réunions de concertation pluridisciplinaire (RCP) : connaître les principes et les objectifs d’une RCP","q":"Quels sont les objectifs principaux des Réunions de Concertation Pluridisciplinaire (RCP) ?","a":"<ul><li>Garantir une <strong>décision collégiale et pertinente</strong>, en conformité avec les référentiels.</li><li>Initialement développées en <strong>oncologie</strong>, les RCP sont désormais étendues aux maladies nécessitant une prise en charge complexe.</li><li>La participation régulière à des RCP valide le <strong>Développement Professionnel Continu (DPC)</strong> des praticiens.</li></ul>"},{"i":"12640b46c7fc","n":5,"o":"5-21","u":"Définition","t":"Listes de vérification ou check-lists : connaître les principes et les objectifs des listes de vérification","q":"Quels sont les objectifs d'une liste de vérification au bloc opératoire ?","a":"<ul><li>Normaliser les échanges et faciliter la <strong>communication</strong> au sein de l'équipe.</li><li>Vérifier l'<strong>identité du patient</strong>, le <strong>type d'intervention</strong>, le <strong>site opératoire</strong>, le <strong>matériel</strong> et les <strong>risques</strong> éventuels.</li><li>Prévenir les <strong>événements indésirables</strong>.</li></ul>"},{"i":"6b4abcd1a0fd","n":5,"o":"5-21","u":"Définition","t":"Listes de vérification ou check-lists : connaître les principes et les objectifs des listes de vérification","q":"Quels sont les trois temps de pause classiques d'une liste de vérification au bloc opératoire ?","a":"<ul><li><strong>Avant l'induction anesthésique</strong></li><li><strong>Avant l'incision</strong> (appelé « time-out »)</li><li><strong>Après l'intervention</strong> (avant la sortie de salle)</li></ul>"},{"i":"a56a2f12405b","n":5,"o":"5-21","u":"Définition","t":"Listes de vérification ou check-lists : connaître les principes et les objectifs des listes de vérification","q":"Quel est l'impact démontré de la check-list « Sécurité du patient au bloc opératoire » ?","a":"<p>La check-list « Sécurité du patient au bloc opératoire » a démontré une <strong>diminution de la morbimortalité postopératoire</strong>.</p>"},{"i":"d0a1ed9d2c0f","n":5,"o":"5-21","u":"Définition","t":"Listes de vérification ou check-lists : connaître les principes et les objectifs des listes de vérification","q":"Quelle est la définition d'une liste de vérification (check-list) en contexte médical ?","a":"<p>Une liste de vérification est un <strong>outil de sécurité</strong>, initialement inspiré de l'aéronautique, utilisé pour structurer la communication et la vérification croisée au sein d'une équipe, notamment au bloc opératoire.</p>"},{"i":"53d6fede47a1","n":5,"o":"5-22","u":"Définition","t":"Réunions de morbi-mortalité (RMM) : connaître les principes et les objectifs d’une RMM","q":"Quel est l'objectif principal d'une Réunion de Morbi-Mortalité (RMM) ?","a":"<p>L'objectif d'une RMM est de mettre en œuvre des <strong>actions de prévention</strong>, de <strong>récupération</strong> ou d'<strong>atténuation</strong> afin d'éviter la récidive des événements indésirables associés aux soins.</p>"},{"i":"6431479a1d4f","n":5,"o":"5-22","u":"Définition","t":"Réunions de morbi-mortalité (RMM) : connaître les principes et les objectifs d’une RMM","q":"Quelle est la définition d'une Réunion de Morbi-Mortalité (RMM) ?","a":"<p>La Réunion de Morbi-Mortalité (RMM) est une <strong>analyse collective et rétrospective</strong> de cas marqués par un <strong>Événement Indésirable Associé aux Soins (EIAS)</strong>. Cela inclut les <strong>décès</strong>, les <strong>complications</strong>, et tout événement qui aurait pu causer un dommage (<strong>presque-accident</strong>).</p>"},{"i":"bbc9f95c1680","n":5,"o":"5-22","u":"Définition","t":"Réunions de morbi-mortalité (RMM) : connaître les principes et les objectifs d’une RMM","q":"Quels sont les principes fondamentaux à respecter lors de l'analyse menée en Réunion de Morbi-Mortalité (RMM) ?","a":"<ul><li>Elle doit se dérouler dans un <strong>climat de confiance et constructif</strong>, non culpabilisant.</li><li>L'analyse doit être <strong>globale et systémique</strong>, prenant en compte les composantes organisationnelles, techniques et humaines.</li><li>Elle dépasse la seule réflexion centrée sur l'individu.</li><li>La RMM intègre un temps explicite de <strong>formation</strong> et est une méthode validante de <strong>Développement Professionnel Continu (DPC)</strong>.</li></ul>"},{"i":"31e918bf6641","n":5,"o":"5-23","u":"Prise en charge","t":"Connaître l’organisation des urgences (SAMU, SMUR, structures d’urgences et spécialisées) et la gestion d’un appel d’urgence","q":"Où sont implantées les structures dédiées à la régulation médicale des urgences en France ?","a":"<p>En France, la structure dédiée est le <strong>SAMU-Centre 15</strong> (centre de réception et de régulation des appels, CRRA), implantée généralement au cœur du <strong>secteur des urgences d'un hôpital</strong>.</p>"},{"i":"3497428803a4","n":5,"o":"5-23","u":"Prise en charge","t":"Connaître l’organisation des urgences (SAMU, SMUR, structures d’urgences et spécialisées) et la gestion d’un appel d’urgence","q":"Quelles sont les différentes réponses possibles qu'un médecin régulateur du SAMU-Centre 15 peut déclencher suite à un appel d'urgence ?","a":"<ul><li>Un <strong>simple conseil médical</strong>.</li><li>L'envoi du <strong>médecin généraliste de permanence</strong> (PDSA).</li><li>L'envoi d'une <strong>ambulance</strong>.</li><li>L'intervention du <strong>SMUR</strong> (service mobile d'urgence et de réanimation).</li></ul>"},{"i":"4180c4d7754e","n":5,"o":"5-23","u":"Prise en charge","t":"Connaître l’organisation des urgences (SAMU, SMUR, structures d’urgences et spécialisées) et la gestion d’un appel d’urgence","q":"Quel est un exemple concret de l'optimisation des « justes soins » par la régulation médicale en cas d'urgence grave ?","a":"<p>Devant une <strong>douleur thoracique</strong> évoquant un <strong>syndrome coronarien aigu</strong>, le SAMU-Centre 15 envoie immédiatement un <strong>SMUR</strong> et oriente directement le patient vers l'<strong>unité de coronarographie</strong>, mobilisant le coronarographiste d'astreinte avant même l'arrivée du patient.</p>"},{"i":"47ce2cc8c6f4","n":5,"o":"5-23","u":"Prise en charge","t":"Connaître l’organisation des urgences (SAMU, SMUR, structures d’urgences et spécialisées) et la gestion d’un appel d’urgence","q":"Quelle est la définition de la régulation médicale dans le cadre de l'aide médicale urgente et quel est son rôle principal ?","a":"<p>La régulation médicale est un <strong>acte médical de télémédecine</strong> pratiqué au téléphone par des médecins régulateurs de l'aide médicale urgente (AMU) et des médecins régulateurs généralistes. Elle constitue le <strong>point d'entrée</strong> de la gestion d'un appel d'urgence.</p>"},{"i":"6e39c616f12e","n":5,"o":"5-3","u":"Définition","t":"Connaître la définition de la responsabilité civile","q":"Quelles sont les trois conditions cumulatives nécessaires pour engager la responsabilité civile ?","a":"<ul><li>Une <strong>faute</strong> que le patient doit prouver.</li><li>Un <strong>préjudice</strong> (dommage subi).</li><li>Un <strong>lien de causalité certain</strong> entre la faute et le préjudice.</li></ul>"},{"i":"836c143bdeec","n":5,"o":"5-3","u":"Définition","t":"Connaître la définition de la responsabilité civile","q":"Dans quel cas la responsabilité civile d'un médecin salarié d'un établissement privé n'est-elle pas directement engagée ?","a":"<p>Pour un médecin salarié d'un établissement privé, c'est généralement l'<strong>employeur</strong> qui répond civilement, sauf s'il y a <strong>dépassement de la mission</strong> par le médecin.</p>"},{"i":"9ba2894b6dbf","n":5,"o":"5-3","u":"Définition","t":"Connaître la définition de la responsabilité civile","q":"Donnez des exemples de professionnels ou structures dont la responsabilité civile peut être engagée.","a":"<ul><li>Les <strong>médecins libéraux</strong> et les <strong>établissements de santé privés</strong>.</li><li>Les <strong>praticiens hospitaliers</strong> dans le cadre de leur secteur d'activité libérale.</li><li>Exceptionnellement, un médecin hospitalier pour une <strong>faute personnelle détachable du service</strong>.</li></ul>"},{"i":"da99359f2dbd","n":5,"o":"5-3","u":"Définition","t":"Connaître la définition de la responsabilité civile","q":"Quelle est la finalité principale de la responsabilité civile en droit médical ?","a":"<p>La responsabilité civile est une responsabilité <strong>indemnitaire</strong>, visant à <strong>réparer le préjudice de la victime</strong> par l'attribution de <strong>dommages et intérêts</strong>.</p>"},{"i":"4449d1f12237","n":5,"o":"5-4","u":"Définition","t":"Connaître la définition de la responsabilité administrative","q":"Quelle est la définition de la responsabilité administrative des médecins ?","a":"<p>La responsabilité administrative est la responsabilité <strong>indemnitaire</strong> qui s'applique aux <strong>médecins salariés du service public hospitalier</strong> (agents publics) et qui aboutit à des <strong>dommages et intérêts</strong> versés à la victime.</p>"},{"i":"48db9faffbee","n":5,"o":"5-4","u":"Définition","t":"Connaître la définition de la responsabilité administrative","q":"Quelles sont les juridictions compétentes en matière de responsabilité administrative ?","a":"<p>Les juridictions compétentes pour la responsabilité administrative sont, par ordre hiérarchique :</p><ul><li>Le <strong>Tribunal administratif</strong></li><li>La <strong>cour administrative d'appel</strong></li><li>Le <strong>Conseil d'État</strong></li></ul>"},{"i":"4c4e62c796f4","n":5,"o":"5-4","u":"Définition","t":"Connaître la définition de la responsabilité administrative","q":"Dans quel cas la responsabilité personnelle du médecin peut-elle être engagée au lieu de la responsabilité administrative de l'hôpital ?","a":"<p>La <strong>faute personnelle détachable du service</strong> engage la responsabilité civile personnelle du médecin (et non l'hôpital) lorsque la faute est :</p><ul><li>Sans lien avec le service.</li><li>Comise dans le service mais détachable par l'<strong>intention de nuire</strong> ou son <strong>exceptionnelle gravité</strong> (ex. refus du chirurgien de garde de se déplacer pour un blessé grave).</p></li></ul>"},{"i":"e9b8d54d183a","n":5,"o":"5-4","u":"Définition","t":"Connaître la définition de la responsabilité administrative","q":"Quels sont les types de fautes engageant la responsabilité administrative du service public ?","a":"<p>Les fautes engageant la responsabilité administrative du service public sont :</p><ul><li>La <strong>faute de service</strong> : faute de l'agent public dans l'exercice de ses fonctions (pendant le service, avec les moyens du service, sans intérêt personnel).</li><li>La <strong>faute dans l'organisation et le fonctionnement du service</strong> : exemple, surveillance insuffisante des patients, mauvais entretien des locaux/matériel, défaut de coordination entre médecins.</li></ul>"},{"i":"3745038e081b","n":5,"o":"5-5","u":"Définition","t":"Connaître la définition de la responsabilité disciplinaire","q":"La responsabilité disciplinaire peut-elle se cumuler avec d'autres types de responsabilités, comme les responsabilités civiles ou pénales ?","a":"<p>Oui, la responsabilité disciplinaire est <strong>indépendante des actions civiles ou pénales</strong>. Un cumul des différentes responsabilités est donc possible.</p>"},{"i":"6056ee810f46","n":5,"o":"5-5","u":"Définition","t":"Connaître la définition de la responsabilité disciplinaire","q":"Quelles sont les sanctions possibles en cas de responsabilité disciplinaire et y a-t-il des sanctions pécuniaires ?","a":"<ul><li>Avertissement.</li><li>Blâme.</li><li><strong>Interdiction temporaire d'exercer</strong> (≤ 3 ans), avec éventuellement un sursis.</li><li><strong>Radiation du tableau de l'Ordre</strong> (un relèvement étant possible après 3 ans).</li></ul><p>Il n'y a <strong>jamais de sanctions pécuniaires</strong> (pas d'amende).</p>"},{"i":"a027fc81ea55","n":5,"o":"5-5","u":"Définition","t":"Connaître la définition de la responsabilité disciplinaire","q":"Qu'est-ce qui caractérise une faute disciplinaire en médecine ?","a":"<p>Une faute disciplinaire est la <strong>violation d'une règle déontologique</strong>, qu'elle soit écrite ou non. Généralement liée à l'activité professionnelle, elle peut aussi concerner un acte de la vie privée portant atteinte à l'honneur de la profession (par exemple, un médecin ivre sur la voie publique).</p>"},{"i":"b8cab649fc5b","n":5,"o":"5-5","u":"Définition","t":"Connaître la définition de la responsabilité disciplinaire","q":"Quelles sont les juridictions ordinales compétentes pour gérer la responsabilité disciplinaire ?","a":"<ul><li>En 1<sup>re</sup> instance : la <strong>chambre disciplinaire du conseil régional de l'Ordre</strong>.</li><li>En appel : la <strong>chambre disciplinaire du conseil national</strong>.</li><li>En cassation : le <strong>Conseil d'État</strong>.</li></ul>"},{"i":"e9547e59df84","n":5,"o":"5-5","u":"Définition","t":"Connaître la définition de la responsabilité disciplinaire","q":"Qu'est-ce que la responsabilité disciplinaire en médecine et devant quelle instance est-elle encourue ?","a":"<p>La responsabilité disciplinaire, également appelée ordinale, sanctionne tout manquement aux règles de <strong>déontologie médicale</strong>. Elle est encourue devant les <strong>instances de l'Ordre des médecins</strong>.</p>"},{"i":"f706ad662158","n":5,"o":"5-5","u":"Définition","t":"Connaître la définition de la responsabilité disciplinaire","q":"Quel est le processus initial lorsqu'une plainte est déposée par un patient concernant une faute disciplinaire ?","a":"<p>La plainte est d'abord transmise au <strong>conseil départemental</strong> qui a l'obligation de tenter une <strong>conciliation</strong>. En cas d'échec de cette conciliation, la plainte est ensuite transmise à la chambre disciplinaire régionale.</p>"},{"i":"7a1f24eb4549","n":5,"o":"5-6","u":"Définition","t":"Connaître la définition de la responsabilité sans faute","q":"Qui assure l'indemnisation dans le cadre de la responsabilité sans faute, et sous quelles conditions ?","a":"<p>L'indemnisation est assurée au titre de la <strong>solidarité nationale</strong>, par l'<strong>ONIAM</strong> (Office National d'Indemnisation des Accidents Médicaux). Elle intervient lorsque le dommage présente des <strong>conséquences anormales</strong> (plus grave que l'évolution naturelle attendue, ou de survenue peu probable &lt; 5%) et atteint un <strong>seuil de gravité</strong> défini.</p>"},{"i":"81fcd4939cfe","n":5,"o":"5-6","u":"Définition","t":"Connaître la définition de la responsabilité sans faute","q":"Quelles sont les trois situations de responsabilité sans faute prévues par la loi en France ?","a":"<ul><li>Une <strong>infection nosocomiale</strong> contractée en établissement de santé.</li><li>Un <strong>accident médical non fautif</strong> (ou aléa thérapeutique), défini comme une complication imprévisible et inévitable.</li><li>Le <strong>défaut d'un produit de santé</strong>, lorsqu'un produit n'offre pas la sécurité légitimement attendue.</li></ul>"},{"i":"fabddcb64da0","n":5,"o":"5-6","u":"Définition","t":"Connaître la définition de la responsabilité sans faute","q":"Quelle est la définition de la responsabilité sans faute en droit médical français ?","a":"<p>La responsabilité sans faute est un régime juridique d'exception qui permet l'indemnisation d'un préjudice subi par un patient alors qu'<strong>aucune faute n'est exigée</strong> du professionnel ou de l'établissement de santé. L'indemnisation est due à partir d'un autre fait générateur que la faute.</p>"},{"i":"0d1d3cd567cd","n":5,"o":"5-7","u":"Définition","t":"Connaître la définition de la faute","q":"Quels sont les différents types de fautes techniques en médecine ?","a":"<ul><li>La <strong>violation des données acquises de la science</strong> : non-respect des recommandations de bonnes pratiques ou de la littérature scientifique médicale.</li><li>La <strong>violation d'un devoir d'humanisme</strong> : atteinte au secret professionnel, ou défaut d'information ne permettant pas un consentement libre et éclairé.</li></ul>"},{"i":"73e7f6db2244","n":5,"o":"5-7","u":"Définition","t":"Connaître la définition de la faute","q":"Quelle est la définition de la faute médicale en droit français ?","a":"<p>La faute médicale est un <strong>manquement à une obligation</strong>, apprécié par rapport à ce qu'aurait fait un praticien normalement diligent. C'est le fait générateur habituel de la responsabilité, et il incombe au patient de la prouver.</p>"},{"i":"c60783ef1fcc","n":5,"o":"5-7","u":"Définition","t":"Connaître la définition de la faute","q":"Quelles sont les dénominations spécifiques de la faute selon les ordres de juridiction ?","a":"<ul><li>En responsabilité administrative, on parle de <strong>faute de service</strong>.</li><li>Devant les instances ordinales, on parle de <strong>faute disciplinaire</strong>, qui est un manquement à la déontologie.</li></ul>"},{"i":"de9faadbf970","n":5,"o":"5-7","u":"Définition","t":"Connaître la définition de la faute","q":"Comment la faute est-elle gradée en droit pénal ?","a":"<ul><li><strong>Faute simple</strong> : Maladresse, imprudence, inattention.</li><li><strong>Faute qualifiée</strong> : A créé ou contribué à créer la situation du dommage ; regroupe la faute délibérée et la faute caractérisée.</li><li><strong>Faute délibérée</strong> : Violation consciente d'une règle de prudence ou de sécurité prévue par la loi.</li><li><strong>Faute caractérisée</strong> : Exposition à un risque de particulière gravité que le médecin ne pouvait ignorer.</li></ul>"},{"i":"564b2171c89c","n":5,"o":"5-8","u":"Définition","t":"Connaître la définition de l’erreur médicale","q":"Quels sont les différents types d'erreurs médicales ?","a":"<ul><li><strong>Erreur par omission</strong> : une action nécessaire n'a pas été faite.</li><li><strong>Erreur par commission</strong> : une action a été faite mais n'était pas utile.</li><li><strong>Erreur d'exécution</strong> : une action a été mal réalisée.</li><li><strong>Violation (non-conformité)</strong> : non-respect d'une recommandation ou d'une règle professionnelle. Elle peut être routinière, par priorisation personnelle ou induite par le contexte.</li></ul>"},{"i":"5d6ab8a69176","n":5,"o":"5-8","u":"Définition","t":"Connaître la définition de l’erreur médicale","q":"Quelle est la définition de l'erreur médicale ?","a":"<p>L'erreur médicale est un <strong>acte de soins</strong> (prévention, diagnostic ou traitement) qui <strong>s'écarte de ce qui aurait dû être fait</strong>. Elle est par nature <strong>involontaire et évitable</strong>, et peut ou non avoir entraîné un dommage pour le patient.</p>"},{"i":"ab4c0f906f16","n":5,"o":"5-8","u":"Définition","t":"Connaître la définition de l’erreur médicale","q":"Quelle est la distinction entre une erreur médicale et un aléa thérapeutique ?","a":"<p>L'<strong>erreur médicale est évitable</strong> et implique un écart par rapport aux bonnes pratiques. L'<strong>aléa thérapeutique est inévitable</strong>, ne résulte d'aucune erreur ni faute, et constitue une complication inattendue et imprévisible d'un acte médical.</p>"},{"i":"667194bbbad6","n":5,"o":"5-9","u":"Définition","t":"Connaître la définition de l’accident médical et de l’affection iatrogène","q":"Quelle est la définition de l'accident médical en droit de la santé ?","a":"<p>L'accident médical est un événement imprévu causant un dommage au patient, présentant un lien de causalité certain avec l'acte médical (diagnostic, soin ou prévention).</p>"},{"i":"accfd0c7c553","n":5,"o":"5-9","u":"Définition","t":"Connaître la définition de l’accident médical et de l’affection iatrogène","q":"Quelle est la définition de l'affection iatrogène en droit de la santé ?","a":"<p>L'affection iatrogène est un dommage dont la cause est l'acte de soin lui-même, c'est-à-dire que les soins délivrés ont provoqué ce dommage. Le terme \"iatrogène\" signifie \"provoqué par le médecin ou le traitement\", par exemple un effet indésirable médicamenteux.</p>"},{"i":"ad0d703982d2","n":5,"o":"5-9","u":"Définition","t":"Connaître la définition de l’accident médical et de l’affection iatrogène","q":"Quelles sont les caractéristiques communes de l'accident médical et de l'affection iatrogène concernant l'indemnisation ?","a":"<ul><li>Ces deux situations désignent des dommages liés aux soins survenant indépendamment de toute erreur.</li><li>Ils font partie, avec l'infection nosocomiale, du périmètre indemnisé par l'<strong>ONIAM</strong> (Office National d'Indemnisation des Accidents Médicaux).</li><li>Ils peuvent être fautifs ou non fautifs. En cas de caractère non fautif et si le seuil de gravité est atteint (<strong>AIPP &gt; 24 %</strong>), ils relèvent de l'aléa thérapeutique et de la solidarité nationale (ONIAM).</li></ul>"}]};